// ExportMappingsCSV is the resolver for the exportMappingsCSV field.
func (r *queryResolver) ExportMappingsCSV(ctx context.Context, input *model.ListMappingsInput) (string, error) {
	if r.MappingStore == nil {
		return "", fmt.Errorf("terminology mapping store not configured")
	}

	// Build filter from input (use large limit for export)
	filter := termdb.ListMappingsFilter{
		Limit:  10000, // Max export size
		Offset: 0,
	}

	if input != nil {
		if input.SourceSystem != nil {
			filter.SourceSystem = *input.SourceSystem
		}
		if input.TargetSystem != nil {
			filter.TargetSystem = *input.TargetSystem
		}
		if input.ProfileID != nil {
			filter.ProfileID = *input.ProfileID
		}
		if input.Origin != nil {
			filter.Origin = toDBOrigin(*input.Origin)
		}
		if input.Equivalence != nil {
			filter.Equivalence = toDBEquivalence(*input.Equivalence)
		}
		if input.CreatedAfter != nil {
			filter.CreatedAfter = input.CreatedAfter
		}
		if input.CreatedBefore != nil {
			filter.CreatedBefore = input.CreatedBefore
		}
	}

	mappings, _, err := r.MappingStore.ListMappings(ctx, filter)
	if err != nil {
		return "", fmt.Errorf("listing mappings for export: %w", err)
	}

	// Build CSV content
	var buf bytes.Buffer
	buf.WriteString("source_system,source_code,source_display,target_system,target_code,target_display,equivalence,confidence,origin,comment,created_at\n")

	for _, m := range mappings {
		// Escape CSV fields
		sourceDisplay := escapeCSV(m.SourceDisplay)
		targetDisplay := escapeCSV(m.TargetDisplay)
		comment := escapeCSV(m.Comment)

		confidence := ""
		if m.Confidence != nil {
			confidence = fmt.Sprintf("%.4f", *m.Confidence)
		}

		buf.WriteString(fmt.Sprintf("%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s\n",
			escapeCSV(m.SourceSystem),
			escapeCSV(m.SourceCode),
			sourceDisplay,
			escapeCSV(m.TargetSystem),
			escapeCSV(m.TargetCode),
			targetDisplay,
			string(m.Equivalence),
			confidence,
			string(m.Origin),
			comment,
			m.CreatedAt.Format(time.RFC3339),
		))
	}

	return buf.String(), nil
}

// ResolveMapping is the resolver for the resolveMapping field.
func (r *queryResolver) ResolveMapping(ctx context.Context, input model.ResolveMappingInput) (*model.ResolveMappingResult, error) {
	start := time.Now()

	// Step 1: Check persistent mappings first
	if r.MappingStore != nil {
		profileID := ""
		if input.ProfileID != nil {
			profileID = *input.ProfileID
		}

		existing, err := r.MappingStore.LookupMapping(ctx, input.SourceSystem, input.SourceCode, input.TargetSystem, profileID)
		if err != nil {
			return nil, fmt.Errorf("persistent lookup failed: %w", err)
		}

		if existing != nil {
			// Found in persistent storage
			return &model.ResolveMappingResult{
				Found:      true,
				Decision:   model.AutorouteDecisionPersistentHit,
				Mapping:    toGraphQLMapping(existing),
				Candidates: []model.MappingCandidate{},
				Confidence: existing.Confidence,
				DurationMs: int(time.Since(start).Milliseconds()),
			}, nil
		}
	}

	// Check if autoroute is disabled
	if input.AllowAutoroute != nil && !*input.AllowAutoroute {
		return &model.ResolveMappingResult{
			Found:      false,
			Decision:   model.AutorouteDecisionNoMatch,
			Candidates: []model.MappingCandidate{},
			DurationMs: int(time.Since(start).Milliseconds()),
		}, nil
	}

	// Step 2: Use autoroute engine if available
	if r.AutorouteEngine == nil {
		return &model.ResolveMappingResult{
			Found:      false,
			Decision:   model.AutorouteDecisionNoMatch,
			Candidates: []model.MappingCandidate{},
			Reasoning:  strPtr("Autoroute engine not configured"),
			DurationMs: int(time.Since(start).Milliseconds()),
		}, nil
	}

	// Build autoroute request
	sourceDisplay := ""
	if input.SourceDisplay != nil {
		sourceDisplay = *input.SourceDisplay
	}
	profileID := ""
	if input.ProfileID != nil {
		profileID = *input.ProfileID
	}

	result, err := r.AutorouteEngine.Suggest(ctx, autoroute.SuggestRequest{
		SourceCode:    input.SourceCode,
		SourceSystem:  input.SourceSystem,
		SourceDisplay: sourceDisplay,
		TargetSystem:  input.TargetSystem,
		ProfileID:     profileID,
		MaxCandidates: 5,
	})
	if err != nil {
		return nil, fmt.Errorf("autoroute failed: %w", err)
	}

	// Determine confidence threshold
	minConfidence := 0.7
	if input.MinConfidence != nil {
		minConfidence = *input.MinConfidence
	}

	// Classify decision
	decision := classifyAutorouteDecision(result.Confidence)

	// Build response
	response := &model.ResolveMappingResult{
		Found:      result.BestMatch != nil && result.Confidence >= minConfidence,
		Decision:   decision,
		Candidates: convertAutorouteCandidates(result),
		Confidence: &result.Confidence,
		Reasoning:  strPtr(result.Reasoning),
		DurationMs: int(time.Since(start).Milliseconds()),
	}

	// Include best match as mapping if confidence meets threshold
	if result.BestMatch != nil && result.Confidence >= minConfidence {
		response.Mapping = &model.CodeMapping{
			ID:            "autoroute-suggestion",
			SourceSystem:  input.SourceSystem,
			SourceCode:    input.SourceCode,
			TargetSystem:  result.BestMatch.System,
			TargetCode:    result.BestMatch.Code,
			TargetDisplay: strPtr(result.BestMatch.Display),
			Equivalence:   toGraphQLEquivalence(result.BestMatch.Equivalence),
			Confidence:    &result.Confidence,
			Origin:        model.MappingOriginApprovedAutoroute,
			CreatedAt:     time.Now(),
		}
	}

	// Include trace if available
	if result.Trace != nil {
		response.Trace = convertAutorouteTrace(result.Trace)
	}

	return response, nil
}

// SuggestMappings is the resolver for the suggestMappings field.
func (r *queryResolver) SuggestMappings(ctx context.Context, input model.SuggestMappingsInput) ([]model.MappingCandidate, error) {
	if r.AutorouteEngine == nil {
		return []model.MappingCandidate{}, nil
	}

	// Build autoroute request
	sourceDisplay := ""
	if input.SourceDisplay != nil {
		sourceDisplay = *input.SourceDisplay
	}
	maxCandidates := 5
	if input.MaxCandidates != nil {
		maxCandidates = *input.MaxCandidates
	}

	result, err := r.AutorouteEngine.Suggest(ctx, autoroute.SuggestRequest{
		SourceCode:    input.SourceCode,
		SourceSystem:  input.SourceSystem,
		SourceDisplay: sourceDisplay,
		TargetSystem:  input.TargetSystem,
		MaxCandidates: maxCandidates,
	})
	if err != nil {
		return nil, fmt.Errorf("autoroute suggestion failed: %w", err)
	}

	return convertAutorouteCandidates(result), nil
}

// ListPendingAutoroutes is the resolver for the listPendingAutoroutes field.
func (r *queryResolver) ListPendingAutoroutes(ctx context.Context, input *model.ListPendingAutoroutesInput) (*model.PendingAutorouteConnection, error) {
	if r.MappingStore == nil {
		return nil, fmt.Errorf("terminology mapping store not configured")
	}

	filter := termdb.ListPendingAutoroutesFilter{
		Limit:  50,
		Offset: 0,
	}

	if input != nil {
		if input.Status != nil {
			filter.Status = toDBPendingStatus(*input.Status)
		}
		if input.MinConfidence != nil {
			filter.MinConfidence = input.MinConfidence
		}
		if input.SourceSystem != nil {
			filter.SourceSystem = *input.SourceSystem
		}
		if input.TargetSystem != nil {
			filter.TargetSystem = *input.TargetSystem
		}
		if input.First != nil && *input.First > 0 {
			filter.Limit = *input.First
		}
		if input.Offset != nil && *input.Offset > 0 {
			filter.Offset = *input.Offset
		}
	}

	pending, total, err := r.MappingStore.ListPendingAutoroutes(ctx, filter)
	if err != nil {
		return nil, fmt.Errorf("listing pending autoroutes: %w", err)
	}

	nodes := make([]model.PendingAutoroute, 0, len(pending))
	for _, p := range pending {
		nodes = append(nodes, *toGraphQLPendingAutoroute(p))
	}

	hasNextPage := filter.Offset+len(pending) < total
	hasPrevPage := filter.Offset > 0

	return &model.PendingAutorouteConnection{
		Nodes:      nodes,
		TotalCount: total,
		PageInfo: &model.PageInfo{
			HasNextPage:     hasNextPage,
			HasPreviousPage: hasPrevPage,
		},
	}, nil
}

// GetPendingAutoroute is the resolver for the getPendingAutoroute field.
func (r *queryResolver) GetPendingAutoroute(ctx context.Context, id string) (*model.PendingAutoroute, error) {
	if r.MappingStore == nil {
		return nil, fmt.Errorf("terminology mapping store not configured")
	}

	pendingID, err := strconv.ParseInt(id, 10, 64)
	if err != nil {
		return nil, fmt.Errorf("invalid pending autoroute ID: %w", err)
	}

	pending, err := r.MappingStore.GetPendingAutoroute(ctx, pendingID)
	if err != nil {
		return nil, fmt.Errorf("getting pending autoroute: %w", err)
	}
	if pending == nil {
		return nil, nil // Not found
	}

	return toGraphQLPendingAutoroute(pending), nil
}

// PendingAutorouteStats is the resolver for the pendingAutorouteStats field.
func (r *queryResolver) PendingAutorouteStats(ctx context.Context) (*model.PendingAutorouteStats, error) {
	if r.MappingStore == nil {
		return &model.PendingAutorouteStats{
			PendingCount:  0,
			ApprovedCount: 0,
			RejectedCount: 0,
			ExpiredCount:  0,
		}, nil
	}

	counts, err := r.MappingStore.CountPendingAutoroutes(ctx)
	if err != nil {
		return nil, fmt.Errorf("counting pending autoroutes: %w", err)
	}

	return &model.PendingAutorouteStats{
		PendingCount:  counts[termdb.StatusPending],
		ApprovedCount: counts[termdb.StatusApproved],
		RejectedCount: counts[termdb.StatusRejected],
		ExpiredCount:  counts[termdb.StatusExpired],
	}, nil
}

// TemporalWorkflow is the resolver for the temporalWorkflow field.
func (r *queryResolver) TemporalWorkflow(ctx context.Context, workflowID string, runID *string) (*model.TemporalWorkflow, error) {
	if r.TemporalClient == nil {
		return nil, fmt.Errorf("temporal client not configured")
	}

	runIDStr := ""
	if runID != nil {
		runIDStr = *runID
	}

	desc, err := r.TemporalClient.DescribeWorkflowExecution(ctx, workflowID, runIDStr)
	if err != nil {
		return nil, fmt.Errorf("failed to describe workflow: %w", err)
	}

	info := desc.WorkflowExecutionInfo
	workflow := toGraphQLTemporalWorkflow(info)
	return &workflow, nil
}

// TemporalWorkflows is the resolver for the temporalWorkflows field.
func (r *queryResolver) TemporalWorkflows(ctx context.Context, filter *model.TemporalWorkflowFilter, first *int, after *string) (*model.TemporalWorkflowConnection, error) {
	if r.TemporalClient == nil {
		return nil, fmt.Errorf("temporal client not configured")
	}

	// Build query string for Temporal's visibility API
	query := ""
	if filter != nil {
		var conditions []string
		if filter.WorkflowType != nil {
			conditions = append(conditions, fmt.Sprintf("WorkflowType = '%s'", *filter.WorkflowType))
		}
		if filter.Status != nil {
			conditions = append(conditions, fmt.Sprintf("ExecutionStatus = '%s'", *filter.Status))
		}
		if filter.StartTimeAfter != nil {
			conditions = append(conditions, fmt.Sprintf("StartTime >= '%s'", filter.StartTimeAfter.Format(time.RFC3339)))
		}
		if filter.StartTimeBefore != nil {
			conditions = append(conditions, fmt.Sprintf("StartTime <= '%s'", filter.StartTimeBefore.Format(time.RFC3339)))
		}
		if len(conditions) > 0 {
			query = conditions[0]
			for i := 1; i < len(conditions); i++ {
				query += " AND " + conditions[i]
			}
		}
	}

	// Default to TaskQueue filter if no query
	if query == "" {
		query = fmt.Sprintf("TaskQueue = '%s'", termworkflow.TaskQueue)
	}

	pageSize := 100
	if first != nil && *first > 0 && *first < pageSize {
		pageSize = *first
	}

	var nextPageToken []byte
	if after != nil && *after != "" {
		nextPageToken = []byte(*after)
	}

	resp, err := r.TemporalClient.ListWorkflow(ctx, &workflowservice.ListWorkflowExecutionsRequest{
		Query:         query,
		PageSize:      int32(pageSize),
		NextPageToken: nextPageToken,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to list workflows: %w", err)
	}

	var workflows []model.TemporalWorkflow
	for _, info := range resp.Executions {
		workflows = append(workflows, toGraphQLTemporalWorkflow(info))
	}

	// Encode next page token for cursor-based pagination
	var endCursor *string
	hasNextPage := len(resp.NextPageToken) > 0
	if hasNextPage {
		cursor := string(resp.NextPageToken)
		endCursor = &cursor
	}

	return &model.TemporalWorkflowConnection{
		Nodes:      workflows,
		TotalCount: len(workflows),
		PageInfo: &model.PageInfo{
			HasNextPage:     hasNextPage,
			HasPreviousPage: after != nil && *after != "",
			EndCursor:       endCursor,
		},
	}, nil
}

// DebugSession is the resolver for the debugSession query.
func (r *queryResolver) DebugSession(ctx context.Context, id string) (*model.DebugSessionModel, error) {
	r.debugSessionsMu.RLock()
	session, ok := r.debugSessions[id]
	r.debugSessionsMu.RUnlock()

	if !ok {
		return nil, nil
	}

	return toDebugSessionModel(session), nil
}

// WorkflowRunTrace is the resolver for the workflowRunTrace query.
func (r *queryResolver) WorkflowRunTrace(ctx context.Context, runID string) ([]model.TraceSpanModel, error) {
	r.workflowRunTracesMu.RLock()
	defer r.workflowRunTracesMu.RUnlock()

	spans, ok := r.workflowRunTraces[runID]
	if !ok {
		return []model.TraceSpanModel{}, nil
	}

	out := make([]model.TraceSpanModel, len(spans))
	copy(out, spans)
	return out, nil
}

